def main(out_path):
    seq = 0
    pages = []
    for folio, desc, cands, conf, la, it, de in P:
        if folio.startswith(("cover", "back_flyleaf", "edge_", "spine")):
            page = None
        else:
            seq += 1
            page = str(seq)
        crib = []
        for word in la + it + de:
            if word not in crib:
                crib.append(word)
        pages.append({
            "page": page,
            "folio": folio,
            "description": desc,
            "candidates_en": cands,
            "confidence": conf,
            "crib": crib,
            "crib_by_language": {"la": la, "it": it, "de": de},
        })
    folios = [p["folio"] for p in pages]
    assert len(folios) == len(set(folios)) == 213, len(folios)
    doc = {
        "source": "Yale Beinecke MS 408 (Cipher manuscript) page scans, image IDs 1006074-1006279, supplied as six PDFs by the user",
        "method": "Visual identification from the scans only; no external Voynich identification literature consulted in this session. AI-generated, exploratory.",
        "page_numbering": "'page' counts scan images in order from 1r = 1 (so 2v = 4); covers have page null. 'folio' is the foliation on the scan. Fold-outs scanned as one image are one entry (e.g. '69v+70r', '71v+72r'); a side scanned in two images is split ('70v_part1', '70v_part2'). Binding photographs (back flyleaf, edges, spine, back cover) have page null. Folios 12, 59-64, 74, 91-92, 97-98 and 109-110 are absent from the scans.",
        "crib_languages": {"la": "medieval Latin herbal/apothecary names", "it": "Italian vernacular (Tuscan/northern forms)", "de": "Middle/Early New High German"},
        "pages": pages,
    }
    with open(out_path, "w", encoding="utf-8") as f:
        json.dump(doc, f, ensure_ascii=False, indent=2)
        f.write("\n")


if __name__ == "__main__":
    main(sys.argv[1])
